import type { MediaKeeper } from './wake';

const MP4 = 'data:video/mp4;base64,';
const WEBM = 'data:video/webm;base64,';

export function createVideoKeeper(owner: Document = document): MediaKeeper {
  let video: HTMLVideoElement | undefined;
  let unusable = false;

  function build(): HTMLVideoElement | undefined {
    const element = owner.createElement('video');
    const source = element.canPlayType('video/mp4') ? MP4 : element.canPlayType('video/webm') ? WEBM : '';
    if (!source) return undefined;
    element.className = 'wake-video';
    element.src = source;
    element.muted = true;
    element.defaultMuted = true;
    element.loop = true;
    element.playsInline = true;
    element.disablePictureInPicture = true;
    element.preload = 'auto';
    element.setAttribute('muted', '');
    element.setAttribute('playsinline', '');
    element.setAttribute('aria-hidden', 'true');
    element.setAttribute('tabindex', '-1');
    element.addEventListener('ended', () => { void element.play().catch(() => undefined); });
    owner.body?.append(element);
    return element;
  }

  return {
    async start() {
      if (unusable) return false;
      if (!video) video = build();
      if (!video) { unusable = true; return false; }
      try {
        await video.play();
        return true;
      } catch {
        return false;
      }
    },
    stop() {
      if (!video || video.paused) return;
      video.pause();
    },
  };
}
